sed -i '/serviceScope.launch {/i \        serviceScope.launch {\n            AudioController.userSpeakingFlow.collect { isSpeaking ->\n                if (isSpeaking && assistantState == AssistantState.SPEAKING) {\n                    Log.d("JarvisService", "Local VAD Barge-in detected. Flushing playback.")\n                    geminiLiveClient?.flushPlayback()\n                    updateAssistantState(AssistantState.LISTENING)\n                }\n            }\n        }\n' app/src/main/java/com/example/services/JarvisService.kt
